pipeline {
    agent any

    environment {
        GROUP_NAME = null
        PROJECT_NAME = null
        VERSION = null
        PORT=11005
        DREMOTE_HOST = '20.48.1.67' // 远程服务器地址
        REMOTE_USER = 'root' // 远程服务器用户名
        REMOTE_CREDENTIALS_ID = 'jenkins-server-ssh-private-key' // Jenkins中保存的远程服务器SSH凭证ID
        TIMESTAMP = new Date().format("yyyyMMddHHmmss", TimeZone.getTimeZone('UTC+8'))
    }

    stages {
        stage('Git') {
            steps {
                echo "Trying to checkout code from gitlab branch: ${params.Branch}"
                checkout scmGit(branches: [[name: "${params.Branch}"]], extensions: [], userRemoteConfigs: [[credentialsId: 'SSH-KEY-FOR-GITLAB', url: '${GIALAB_ADDRESS}/common/net-auth.git']])
            }
        }

        // stage('SonarQube Analysis') {
        //     steps {
        //         script {
        //             def pom = readMavenPom file: 'pom.xml'
        //             GROUP_NAME = pom.groupId
        //             PROJECT_NAME = pom.artifactId
        //             VERSION = pom.version
        //         }
        //         withSonarQubeEnv('SonarQube-dev') {
        //           sh "mvn verify sonar:sonar -DskipTests -Dsonar.projectKey=${PROJECT_NAME} -Dsonar.projectName='${PROJECT_NAME}'"
        //         }
        //     }
        // }

        stage('Mvn Compile') {
            steps {
                script {
                    def pom = readMavenPom file: 'pom.xml'
                    GROUP_NAME = pom.groupId
                    PROJECT_NAME = 'net-auth-server'
                    VERSION = pom.properties.revision
                    sh "mvn clean"
                    sh "mvn install -Dmaven.test.skip=true -Ptest"
                }
            }
        }


        stage('Build Image') {
            steps {
                script {
                    try {
                        echo 'try to remove old image before build.'
                        sh "docker rmi ${GROUP_NAME}/${PROJECT_NAME}:${VERSION}"
                        echo 'old image(${GROUP_NAME}/${PROJECT_NAME}:${VERSION}) removed.'
                    } catch (Exception e) {
                        echo 'nothing to remove.'
                    }



                    echo 'try to build the image.'
                    sh "docker build -t ${GROUP_NAME}/${PROJECT_NAME}:${VERSION} -f \"net-auth-server/devops/Dockerfile\" --build-arg group_name=${GROUP_NAME} --build-arg project_name=${PROJECT_NAME} --build-arg version=${VERSION} --build-arg port=${PORT} ."
                    echo 'image(${GROUP_NAME}/${PROJECT_NAME}:${VERSION}) is built.'
                }
            }
        }


        stage('Push Image') {
            steps {
                script {
                    try{
                    def timestamp = new Date().format("yyyyMMddHHmmss", TimeZone.getTimeZone('Asia/Shanghai'))
                        sh " docker login --username=${DOCKER_REGISTRY_USERNAME} --password=${DOCKER_REGISTRY_PASSWORD} ${DOCKER_REGISTRY}"
                        sh " docker tag ${GROUP_NAME}/${PROJECT_NAME}:${VERSION} ${DOCKER_REGISTRY}/${PROJECT_NAME}:${VERSION}-${env.TIMESTAMP}"
                        sh " docker push ${DOCKER_REGISTRY}/${PROJECT_NAME}:${VERSION}-${env.TIMESTAMP}"
                        echo "image(${GROUP_NAME}/${PROJECT_NAME}:${VERSION}-${env.TIMESTAMP}) is pushed to the registry."
                    } catch (Exception e) {
                        echo 'push image failed'
                        echo "Caught exception: ${e.getMessage()}"
                    }
                }
            }
        }

        stage('Deploy to Remote') {
            steps {
                script {
                    if (params.DEPLOY) {
                        sshagent([REMOTE_CREDENTIALS_ID]) {
                            sh """
                                ssh ${REMOTE_USER}@${DREMOTE_HOST} '
                                docker login --username=${DOCKER_REGISTRY_USERNAME} --password=${DOCKER_REGISTRY_PASSWORD} ${DOCKER_REGISTRY}  &&

                                docker pull ${DOCKER_REGISTRY}/${PROJECT_NAME}:${VERSION}-${env.TIMESTAMP} &&

                                docker stop ${PROJECT_NAME} || true &&

                                docker rm ${PROJECT_NAME} || true &&

                                docker run -d --name ${PROJECT_NAME} -p ${PORT}:${PORT} -e TZ=Asia/Shanghai --network=host --restart=always -v /etc/dm_csv.conf ${DOCKER_REGISTRY}/${PROJECT_NAME}:${VERSION}-${env.TIMESTAMP} 
                                '
                               """
                        }
                    } else {
                        echo 'deploy skipped.'
                    }
                }
            }
        }
    }

        // stage('Deploy') {
        //     steps {
        //         script {
        //             if (params.DEPLOY){

        //                 sh "docker rm -f ${PROJECT_NAME} || true "
        //                 sh "docker run -d --name ${PROJECT_NAME} -p ${PORT}:${PORT} ${GROUP_NAME}/${PROJECT_NAME}:${VERSION}"

        //             } else {
        //                 echo 'deploy skipped.'
        //             }
        //         }
        //     }
        // }
}
